import{_ as i,C as n,o as l,c as p,j as t,a as s,E as r,a2 as d}from"./chunks/framework.BiXHgXAn.js";const y=JSON.parse('{"title":"Using go tool task","description":"How to use Task using go tool.","frontmatter":{"title":"Using `go tool task`","description":"How to use Task using go tool.","author":"andreynering","date":"2026-04-14T00:00:00.000Z","tags":["installation"],"outline":"deep","editLink":false},"headers":[],"relativePath":"blog/go-tool-task.md","filePath":"next/blog/go-tool-task.md"}'),c={name:"blog/go-tool-task.md"};function h(e,a,g,k,u,b){const o=n("AuthorCard");return l(),p("div",null,[a[0]||(a[0]=t("h1",{id:"using-go-tool-task",tabindex:"-1"},[s("Using "),t("code",null,"go tool task"),s(),t("a",{class:"header-anchor",href:"#using-go-tool-task","aria-label":'Permalink to "Using `go tool task`"'},"​")],-1)),r(o,{author:e.$frontmatter.author},null,8,["author"]),a[1]||(a[1]=d('<p>Do you know that you can use Task without really needing to install it?</p><p>If you work with Go, you probably depend on external binaries like linters, code generators and... Task.</p><p>But asking your coworkers or contributors to install dependencies can be messy. Everyone is on a different operating system, use a different package manager, etc. In fact, <a href="https://taskfile.dev/docs/installation" target="_blank" rel="noreferrer">Task supports several package managers</a>, but even having to choose how you want to install it can lead to some fatigue.</p><p>Well, turns out you can just use <code>go tool</code>!</p><p>Step one: add Task as a tool to your Go project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/go-task/task/v3/cmd/task@latest</span></span></code></pre></div><p>The command above will add a line like this to your <code>go.mod</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tool github.com/go-task/task/v3/cmd/task</span></span></code></pre></div><p>Step two: prefix <code>go tool</code> when calling Task:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {arguments...}</span></span></code></pre></div><p>That&#39;s all!</p><p>Go will compile the specified Task version on demand when calling <code>go tool task</code>. Don&#39;t worry, Go caches the tool, so subsequent calls are faster.</p><p>This is useful when running Task on CI, as you don&#39;t need to stress about having to install it. It also means it&#39;ll be pinned to a specific Task version (but Dependabot or Renovate should be able to update it for you).</p>',13))])}const v=i(c,[["render",h]]);export{y as __pageData,v as default};
